properties.query:
// AlertBacked incidents carry no SOCRadar-Alarm-<id> label (only the plain
// SOCRadar label), and Defender's correlation engine can rename the title away
// from the #<id> the import wrote. When the title no longer has it, fall back
// to the AlarmId custom detail recorded on the incident's one backing alert.
SecurityIncident
| summarize arg_max(TimeGenerated, *) by IncidentNumber
| where Labels has "SOCRadar"
| where Status == "Closed"
| where LastModifiedTime < ago(30m)
| where not(Labels has "Synced")
| extend AlarmId = extract(@"#(\d+)", 1, Title)
| extend AlertGuid = tostring(todynamic(AlertIds)[0])
| join kind=leftouter (
    SecurityAlert
    | summarize arg_max(TimeGenerated, *) by SystemAlertId
    // Custom details land in ExtendedProperties['Custom Details'] as a second,
    // still-encoded JSON string (not a nested object), and each value is a
    // 1-element array (live-measured, 2 Nov 2026).
    | extend AlarmIdFromAlert = tostring(parse_json(tostring(parse_json(tostring(ExtendedProperties))['Custom Details'])).AlarmId[0])
) on $left.AlertGuid == $right.SystemAlertId
| extend AlarmId = coalesce(AlarmId, AlarmIdFromAlert)
| extend AccountName = AlarmId
| project TimeGenerated, IncidentName, Title, Status, Classification, LastModifiedTime, AlarmId, AccountName
